import {
  PlaneGeometry,
  Mesh,
  Group,
  DoubleSide,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import {
  texture,
  uv,
  vec2,
  vec3,
  vec4,
  sin,
  dot,
  fract,
  float,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'features-card-2-floating-accent';

  // atlas region 0,0,512,320 -> aspect 1.6
  const rectW = 512;
  const rectH = 320;
  const aspect = rectW / rectH;

  const planeWidth = 1.4;
  const planeHeight = planeWidth / aspect;

  const geometry = new PlaneGeometry(planeWidth, planeHeight, 1, 1);

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    depthWrite: false,
  });

  // Subtle engineered grain overlay via TSL — applied once map is ready.
  const buildColorNode = (mapTex) => {
    const uvNode = uv();
    const texNode = texture(mapTex, uvNode);

    // deterministic pseudo-random grain (no time dependency -> stays static)
    const grainSeed = uvNode.mul(4096.0);
    const rand = fract(
      sin(dot(grainSeed, vec2(12.9898, 78.233))).mul(43758.5453)
    );
    const grain = rand.sub(0.5).mul(0.035);

    const rgb = texNode.rgb.add(vec3(grain, grain, grain));
    return vec4(rgb, texNode.a);
  };

  const mesh = new Mesh(geometry, material);
  mesh.name = 'floating-accent-plane';
  mesh.renderOrder = 5;
  group.add(mesh);

  // Billboard toward camera every frame (sprite behavior for a plane geometry).
  mesh.onBeforeRender = (renderer, scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  let loadedTexture = null;

  const texturePromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      loadedTexture = tex;
      material.colorNode = buildColorNode(tex);
      material.needsUpdate = true;
    })
    .catch(() => {
      // fall back to a quiet ink-toned card if the asset fails to load
      material.colorNode = vec4(
        float(0.086),
        float(0.086),
        float(0.114),
        float(1.0)
      );
      material.needsUpdate = true;
    });

  // Weighted entrance — respects "static composition" post-settle.
  group.scale.setScalar(0.001);
  material.opacity = 0;
  mesh.position.y = -0.16;

  const timeline = gsap.timeline({ delay: 0.05 });
  timeline
    .to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.7,
      ease: 'power3.out',
    })
    .to(
      mesh.position,
      {
        y: 0,
        duration: 0.7,
        ease: 'power3.out',
      },
      0
    )
    .to(
      material,
      {
        opacity: 1,
        duration: 0.6,
        ease: 'power2.out',
        onUpdate: () => {
          material.needsUpdate = true;
        },
      },
      0.05
    )
    .to(group.scale, {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.0001,
    })
    .to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out',
    });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timeline.kill();
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(mesh.position);
    gsap.killTweensOf(material);

    geometry.dispose();
    material.dispose();

    if (loadedTexture && typeof loadedTexture.dispose === 'function') {
      loadedTexture.dispose();
    }

    mesh.onBeforeRender = () => {};
  };

  return group;
}
